// clamped to at least 1. BFME 2's AFLAME status is bit 10 (ZH's enum has 11),
// tested through the rowed Object::testStatus.

//-------------------------------------------------------------------------------------------------
//-------------------------------------------------------------------------------------------------
UnsignedInt FireSpreadUpdate::calcNextSpreadDelay()
{
	const FireSpreadUpdateModuleData* d = getFireSpreadUpdateModuleData();
	UnsignedInt delay = GetGameLogicRandomValue( d->m_minSpreadTryDelayData, d->m_maxSpreadTryDelayData,
		"C:\\projects\\bfme2patch103\\bfme2\\Code\\GameEngine\\Source\\GameLogic\\Object\\Update\\FireSpreadUpdate.cpp", 152 );
	if (delay < 1)
		delay = 1;
	return delay;
}

//-------------------------------------------------------------------------------------------------
//-------------------------------------------------------------------------------------------------
void FireSpreadUpdate::startFireSpreading()
{
	Object *obj = getObject();
	if( !obj->testStatus( BFME_OBJECT_STATUS_AFLAME ) )
		return;	// sorry, must be on fire

	setWakeFrame(obj, UPDATE_SLEEP(calcNextSpreadDelay()));
}

